def test_single_writer_raw_read_window(tmp_path, monkeypatch):
    # Add to proposed test_runner_output_generation.py beside _economic_rows/_snapshot.
    histories = {"writer-A": _economic_rows(1), "writer-B": _economic_rows(-1)}
    selected = {"name": "writer-B"}
    def offline_load(_path, *, max_records=None):
        name = threading.current_thread().name
        return list(histories[name if name in histories else selected["name"]])
    monkeypatch.setattr(runner, "load_observations", offline_load)
    oracles = {}
    for name in histories:
        selected["name"] = name
        root = tmp_path / name
        runner.run_once(local_dir=root, network=False, external_jsonl=(), as_of_ms=CLOCK)
        oracles[name] = _snapshot(root)
    assert all(oracles["writer-A"][f] != oracles["writer-B"][f] for f in FILES), "non-distinct economic oracle"
    shared = tmp_path / "shared"
    shared.mkdir()
    for f in FILES:
        (shared / f).write_text(json.dumps(oracles["writer-B"][f]), encoding="utf-8")
    reached, release = threading.Event(), threading.Event()
    errors = []
    original = runner.atomic_write_json
    def gated_write(path, payload):
        original(path, payload)
        if threading.current_thread().name == "writer-A" and Path(path).name == "latest.json":
            reached.set()
            assert release.wait(15), "writer release timeout"
    monkeypatch.setattr(runner, "atomic_write_json", gated_write)
    def writer():
        try:
            runner.run_once(local_dir=shared, network=False, external_jsonl=(), as_of_ms=CLOCK)
        except BaseException as exc:
            errors.append(repr(exc))
    thread = threading.Thread(target=writer, name="writer-A")
    thread.start()
    try:
        assert reached.wait(15), "writer never reached latest.json"
        during = _snapshot(shared)
        assert during["latest.json"] == oracles["writer-A"]["latest.json"]
        assert during["audit_latest.json"] == oracles["writer-B"]["audit_latest.json"]
        assert during["anata_latest.json"] == oracles["writer-B"]["anata_latest.json"]
    finally:
        release.set()
        thread.join(20)
    assert not thread.is_alive() and not errors, errors
    assert _snapshot(shared) == oracles["writer-A"]
